import * as THREE from 'three/webgpu'
import { gsap } from 'gsap'

export default function createNode(config, ctx) {
  const group = new THREE.Group()
  const timelines = []

  // Configuration constants
  const CORE_COUNT = 90
  const FIELD_COUNT = 1110
  const PARTICLE_RADIUS = 0.012
  const CORE_SPHERE_RADIUS = 0.5
  const SHELL_CENTER = new THREE.Vector3(0, 0, -1.5)
  const SHELL_AXES = new THREE.Vector3(6, 4, 5)

  const COLORS = {
    background: 0x0b0b10,
    paper: 0xe8ecf2,
    accent: 0xff2a38
  }

  // Generate random points in sphere (for core)
  function generateSpherePoints(count, radius) {
    const positions = new Float32Array(count * 3)
    for (let i = 0; i < count; i++) {
      const phi = Math.acos(2 * Math.random() - 1)
      const theta = Math.random() * Math.PI * 2
      const r = radius * Math.cbrt(Math.random())

      positions[i * 3] = r * Math.sin(phi) * Math.cos(theta)
      positions[i * 3 + 1] = r * Math.sin(phi) * Math.sin(theta)
      positions[i * 3 + 2] = r * Math.cos(phi)
    }
    return positions
  }

  // Generate random points in ellipsoid shell (for field)
  function generateEllipsoidPoints(count) {
    const positions = new Float32Array(count * 3)
    const distances = new Float32Array(count)

    for (let i = 0; i < count; i++) {
      const phi = Math.acos(2 * Math.random() - 1)
      const theta = Math.random() * Math.PI * 2
      const u = Math.random()

      // Shell from r=3 to r=4.5
      const r = 3 + u * 1.5

      // Map to ellipsoid
      const x = r * Math.sin(phi) * Math.cos(theta) * (SHELL_AXES.x / SHELL_AXES.y)
      const y = r * Math.sin(phi) * Math.sin(theta)
      const z = r * Math.cos(phi) * (SHELL_AXES.z / SHELL_AXES.y)

      positions[i * 3] = SHELL_CENTER.x + x
      positions[i * 3 + 1] = SHELL_CENTER.y + y
      positions[i * 3 + 2] = SHELL_CENTER.z + z

      // Distance from core for stagger
      distances[i] = Math.sqrt(x * x + y * y + z * z)
    }

    return { positions, distances }
  }

  const corePositions = generateSpherePoints(CORE_COUNT, CORE_SPHERE_RADIUS)
  const { positions: fieldPositions, distances: fieldDistances } =
    generateEllipsoidPoints(FIELD_COUNT)

  // Create particle geometry (icosahedron)
  const particleGeo = new THREE.IcosahedronGeometry(PARTICLE_RADIUS, 0)

  // Core material: red accent, additive, emissive
  const coreMat = new THREE.MeshStandardMaterial({
    color: COLORS.accent,
    emissive: COLORS.accent,
    emissiveIntensity: 1.8,
    metalness: 0,
    roughness: 1,
    transparent: true,
    blending: THREE.AdditiveBlending,
    depthWrite: false
  })

  // Field material: paper white, additive, self-lit
  const fieldMat = new THREE.MeshStandardMaterial({
    color: COLORS.paper,
    emissive: COLORS.paper,
    emissiveIntensity: 0.9,
    metalness: 0,
    roughness: 1,
    transparent: true,
    blending: THREE.AdditiveBlending,
    depthWrite: false
  })

  // Create core instanced mesh
  const coreMesh = new THREE.InstancedMesh(particleGeo, coreMat, CORE_COUNT)
  for (let i = 0; i < CORE_COUNT; i++) {
    const mat = new THREE.Matrix4()
    mat.setPosition(corePositions[i * 3], corePositions[i * 3 + 1], corePositions[i * 3 + 2])
    coreMesh.setMatrixAt(i, mat)
  }
  coreMesh.instanceMatrix.needsUpdate = true
  group.add(coreMesh)

  // Create field instanced mesh
  const fieldMesh = new THREE.InstancedMesh(particleGeo, fieldMat, FIELD_COUNT)
  for (let i = 0; i < FIELD_COUNT; i++) {
    const mat = new THREE.Matrix4()
    mat.setPosition(fieldPositions[i * 3], fieldPositions[i * 3 + 1], fieldPositions[i * 3 + 2])
    fieldMesh.setMatrixAt(i, mat)
  }
  fieldMesh.instanceMatrix.needsUpdate = true
  group.add(fieldMesh)

  // Apply particle-emerge cinematic primitive
  if (ctx.primitives?.['particle-emerge']) {
    ctx.primitives['particle-emerge'](fieldMesh, {
      count: FIELD_COUNT,
      durationMs: 1400
    })
  }

  // Core pulse animation: emissive intensity 1.8 ↔ 1.5 at 0.1 Hz
  const corePulse = gsap.timeline({ repeat: -1 })
  timelines.push(corePulse)

  corePulse
    .to(
      coreMat,
      {
        emissiveIntensity: 1.5,
        duration: 5,
        ease: 'sine.inOut'
      },
      0
    )
    .to(
      coreMat,
      {
        emissiveIntensity: 1.8,
        duration: 5,
        ease: 'sine.inOut'
      }
    )

  // Ambient drift: particles orbit anchors ±0.04 units at 0.05 Hz
  const driftState = { t: 0 }
  const driftTl = gsap.timeline({ repeat: -1 })
  timelines.push(driftTl)

  driftTl.to(driftState, {
    t: 1,
    duration: 20, // 0.05 Hz = 20s period
    ease: 'none',
    onUpdate: () => {
      const angle = driftState.t * Math.PI * 2

      // Update core particles
      for (let i = 0; i < CORE_COUNT; i++) {
        const x0 = corePositions[i * 3]
        const y0 = corePositions[i * 3 + 1]
        const z0 = corePositions[i * 3 + 2]
        const dist = Math.sqrt(x0 * x0 + y0 * y0 + z0 * z0)

        if (dist > 0.001) {
          const phase = (i / CORE_COUNT) * Math.PI * 2
          const drift = 0.04 * Math.sin(angle + phase)
          const scale = (dist + drift) / dist

          const mat = new THREE.Matrix4()
          mat.setPosition(x0 * scale, y0 * scale, z0 * scale)
          coreMesh.setMatrixAt(i, mat)
        }
      }
      coreMesh.instanceMatrix.needsUpdate = true

      // Update field particles
      for (let i = 0; i < FIELD_COUNT; i++) {
        const x0 = fieldPositions[i * 3]
        const y0 = fieldPositions[i * 3 + 1]
        const z0 = fieldPositions[i * 3 + 2]
        const dist = Math.sqrt(x0 * x0 + y0 * y0 + z0 * z0)

        if (dist > 0.001) {
          const phase = (i / FIELD_COUNT) * Math.PI * 2
          const drift = 0.04 * Math.sin(angle + phase)
          const scale = (dist + drift) / dist

          const mat = new THREE.Matrix4()
          mat.setPosition(x0 * scale, y0 * scale, z0 * scale)
          fieldMesh.setMatrixAt(i, mat)
        }
      }
      fieldMesh.instanceMatrix.needsUpdate = true
    }
  })

  // Text rendering via MSDF font atlas
  const textItems = [
    {
      text: 'NOVA ATELIER',
      family: 'Lora',
      size: 0.62,
      weight: 600,
      y: 0.5
    },
    {
      text: 'Precision instruments for the dark hours.',
      family: 'JetBrains Mono',
      size: 0.2,
      weight: 400,
      y: -0.25
    },
    {
      text: 'EST. 2019 / GENEVA AND KYOTO',
      family: 'JetBrains Mono',
      size: 0.09,
      weight: 400,
      y: -2.25
    }
  ]

  for (const item of textItems) {
    if (ctx.fontAtlas?.createText) {
      const textMesh = ctx.fontAtlas.createText(item.text, {
        family: item.family,
        weight: item.weight,
        size: item.size
      })
      if (textMesh) {
        textMesh.position.set(0, item.y, 0.5)
        group.add(textMesh)
      }
    }
  }

  // Cleanup resources
  group.userData.cleanup = () => {
    particleGeo.dispose()
    coreMat.dispose()
    fieldMat.dispose()
    coreMesh.dispose()
    fieldMesh.dispose()
    timelines.forEach(tl => tl.kill())
  }

  return group
}
